<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\Purchase;use Illuminate\Http\Request;use Illuminate\Validation\Rule;class AdminPurchaseController extends Controller{public function index(Request $r){return response()->json(Purchase::with('user:id,name,email')->when($r->status,fn($q,$s)=>$q->where('status',$s))->latest()->paginate(20));}public function show(Purchase $purchase){return ['data'=>$purchase->load('user:id,name,email','items')];}public function status(Request $r,Purchase $purchase){$d=$r->validate(['status'=>['required',Rule::in(['en_attente','validee','expediee','annulee'])]]);$purchase->update($d);return ['data'=>$purchase];}}
